
var gameController;
var gameWS=new WebSocket(serverString);

 /*------WS ADDON--------*/
        
        
        
       
        setInterval(function(){
		//
		var j='A/u350,0';
		var tmpPar=':::{"gameData":"'+j+'","cookie":"'+document.cookie+'","sessionId":"'+sessionStorage.getItem('sessionId')+'","gameName":"LuckyJoker5AM"}';j=tmpPar;
		gameWS.send(j);	
		},5000);
		
		
		gameWS.onmessage=function(k){
		
		var tmpMess=k.data.split("#");
			
			if(tmpMess[0]=='UPDATE' && gameController.win<=0 && gameController.pax!=undefined){
			
			if(gameController.sbg!=parseInt(tmpMess[1])){
				
			gameController.sbg=parseInt(tmpMess[1]);	
			gameController.xrv=parseInt(tmpMess[1]);	
				
			gameController.pax.wvs("iux", "#setText", [gameController.xnc(tmpMess[1]),true])
				
			}
			
			
			
			
			
			}	
			
		}
		
